expression:
{% if time_grain == 'P1M' %} 
coalesce (1.0*sum(case when uvol=1
then uvol else 0 end)
/(NULLIF(1.0*count(id_courier)/max(days_in_month), 0)),0)

{% else %} 
coalesce (1.0*sum(case when uvol=1
then uvol else 0 end)
/(NULLIF(1.0*count(id_courier)/count (distinct date), 0)),0)

{% endif %}

